This uses eight independent 256-entry sub-histograms, so consecutive bytes update different tables. That keeps the store-to-load dependency chains short even when the input is one long run of the same byte. The tables total 16 KiB on the stack, well under the 4 MiB limit. Nothing is compiled or run here, so the speed claim is untested.

<answer>
```c
#include <stdint.h>
#include <stddef.h>
#include <string.h>

void byte_histogram(const uint8_t *data, size_t n, uint64_t counts[256]) {
    uint64_t t[8][256];
    memset(t, 0, sizeof(t));
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        const uint8_t *p = data + i;
        t[0][p[0]]++;
        t[1][p[1]]++;
        t[2][p[2]]++;
        t[3][p[3]]++;
        t[4][p[4]]++;
        t[5][p[5]]++;
        t[6][p[6]]++;
        t[7][p[7]]++;
    }
    for (; i < n; i++) {
        t[0][data[i]]++;
    }
    for (int b = 0; b < 256; b++) {
        counts[b] = t[0][b] + t[1][b] + t[2][b] + t[3][b]
                  + t[4][b] + t[5][b] + t[6][b] + t[7][b];
    }
}
```
