This uses eight private uint32 sub-histograms, rotated by byte position. Long runs of the same byte then update different tables, which breaks the store-to-load dependency chain on a single counter. Chunks of 16 MiB keep the uint32 counters from overflowing, and the sub-tables total 8 KiB of stack. I have not compiled or run this.

<answer>
```c
#include <stdint.h>
#include <stddef.h>
#include <string.h>

void byte_histogram(const uint8_t *data, size_t n, uint64_t counts[256])
{
    for (int b = 0; b < 256; b++) counts[b] = 0;

    const size_t CH = (size_t)1 << 24; /* 16 MiB chunks: uint32 counters cannot overflow */
    size_t base = 0;
    while (base < n) {
        size_t len = n - base;
        if (len > CH) len = CH;
        const uint8_t *d = data + base;

        uint32_t t[8][256];
        memset(t, 0, sizeof(t));

        size_t i = 0;
        for (; i + 8 <= len; i += 8) {
            t[0][d[i + 0]]++;
            t[1][d[i + 1]]++;
            t[2][d[i + 2]]++;
            t[3][d[i + 3]]++;
            t[4][d[i + 4]]++;
            t[5][d[i + 5]]++;
            t[6][d[i + 6]]++;
            t[7][d[i + 7]]++;
        }
        for (; i < len; i++) {
            t[0][d[i]]++;
        }

        for (int b = 0; b < 256; b++) {
            uint64_t s = (uint64_t)t[0][b] + t[1][b] + t[2][b] + t[3][b]
                       + t[4][b] + t[5][b] + t[6][b] + t[7][b];
            counts[b] += s;
        }

        base += len;
    }
}
```
</answer>

This uses four NEON `float32x4_t` accumulators (16 partial sums) with fused multiply-add, which keeps per-partial-sum rounding error small. The scalar tail handles leftover elements, so empty and tiny sizes work.

<answer>
```c
#include <arm_neon.h>
#include <stddef.h>

float dot_f32(const float *a, const float *b, size_t n) {
    float32x4_t s0 = vdupq_n_f32(0.0f);
    float32x4_t s1 = vdupq_n_f32(0.0f);
    float32x4_t s2 = vdupq_n_f32(0.0f);
    float32x4_t s3 = vdupq_n_f32(0.0f);
    size_t i = 0;
    for (; i + 16 <= n; i += 16) {
        s0 = vfmaq_f32(s0, vld1q_f32(a + i),      vld1q_f32(b + i));
        s1 = vfmaq_f32(s1, vld1q_f32(a + i + 4),  vld1q_f32(b + i + 4));
        s2 = vfmaq_f32(s2, vld1q_f32(a + i + 8),  vld1q_f32(b + i + 8));
        s3 = vfmaq_f32(s3, vld1q_f32(a + i + 12), vld1q_f32(b + i + 12));
    }
    for (; i + 4 <= n; i += 4) {
        s0 = vfmaq_f32(s0, vld1q_f32(a + i), vld1q_f32(b + i));
    }
    float32x4_t t = vaddq_f32(vaddq_f32(s0, s1), vaddq_f32(s2, s3));
    float sum = vaddvq_f32(t);
    for (; i < n; i++) {
        sum += a[i] * b[i];
    }
    return sum;
}
```
