```c
#include <arm_neon.h>
#include <stddef.h>

float dot_f32(const float *a, const float *b, size_t n) {
    float64x2_t s0 = vdupq_n_f64(0.0);
    float64x2_t s1 = vdupq_n_f64(0.0);
    float64x2_t s2 = vdupq_n_f64(0.0);
    float64x2_t s3 = vdupq_n_f64(0.0);
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        float32x4_t p0 = vmulq_f32(vld1q_f32(a + i), vld1q_f32(b + i));
        float32x4_t p1 = vmulq_f32(vld1q_f32(a + i + 4), vld1q_f32(b + i + 4));
        s0 = vaddq_f64(s0, vcvt_f64_f32(vget_low_f32(p0)));
        s1 = vaddq_f64(s1, vcvt_high_f64_f32(p0));
        s2 = vaddq_f64(s2, vcvt_f64_f32(vget_low_f32(p1)));
        s3 = vaddq_f64(s3, vcvt_high_f64_f32(p1));
    }
    s0 = vaddq_f64(vaddq_f64(s0, s1), vaddq_f64(s2, s3));
    double s = vgetq_lane_f64(s0, 0) + vgetq_lane_f64(s0, 1);
    for (; i < n; i++) {
        s += (double)(a[i] * b[i]);
    }
    return (float)s;
}
```
