This is a NEON version that handles four int64 values per iteration and uses non-temporal stores for the output. The output is about 128 MB, so it won't stay in cache, and the stores skip the read-for-ownership traffic. I haven't compiled or run it.

<answer>
```c
#include <stdint.h>
#include <stddef.h>
#include <arm_neon.h>

void prefix_sum_i64(const int64_t *in, int64_t *out, size_t n) {
    int64x2_t zero = vdupq_n_s64(0);
    int64x2_t carry = vdupq_n_s64(0);
    size_t i = 0;
    for (; i + 4 <= n; i += 4) {
        int64x2_t v0 = vld1q_s64(in + i);
        int64x2_t v1 = vld1q_s64(in + i + 2);
        int64x2_t p0 = vaddq_s64(v0, vextq_s64(zero, v0, 1));
        int64x2_t p1 = vaddq_s64(v1, vextq_s64(zero, v1, 1));
        int64x2_t tot = vdupq_laneq_s64(p0, 1);
        p1 = vaddq_s64(p1, tot);
        int64x2_t o0 = vaddq_s64(p0, carry);
        int64x2_t o1 = vaddq_s64(p1, carry);
        int64x2_t blk = vdupq_laneq_s64(p1, 1);
        carry = vaddq_s64(carry, blk);
        __asm__ volatile("stnp %q1, %q2, [%0]"
                         :
                         : "r"(out + i), "w"(o0), "w"(o1)
                         : "memory");
    }
    int64_t c = vgetq_lane_s64(carry, 0);
    for (; i < n; i++) {
        c += in[i];
        out[i] = c;
    }
}
```
</answer>

This uses eight independent uint32 histograms, so consecutive equal bytes update different counters and don't serialize on one store-forwarding chain. That matters for the long-run input. The tables are summed into `counts` at the end of each chunk, and chunks are capped at 2^30 bytes so the uint32 counters cannot overflow. Stack use is about 8 KiB. I have not compiled or benchmarked it.

<answer>
```c
#include <stdint.h>
#include <stddef.h>
#include <string.h>

void byte_histogram(const uint8_t *data, size_t n, uint64_t counts[256]) {
    for (int b = 0; b < 256; b++) counts[b] = 0;
    while (n) {
        size_t chunk = n > ((size_t)1 << 30) ? ((size_t)1 << 30) : n;
        uint32_t h[8][256];
        memset(h, 0, sizeof h);
        size_t i = 0;
        for (; i + 8 <= chunk; i += 8) {
            h[0][data[i]]++;
            h[1][data[i + 1]]++;
            h[2][data[i + 2]]++;
            h[3][data[i + 3]]++;
            h[4][data[i + 4]]++;
            h[5][data[i + 5]]++;
            h[6][data[i + 6]]++;
            h[7][data[i + 7]]++;
        }
        for (; i < chunk; i++) h[0][data[i]]++;
        for (int b = 0; b < 256; b++) {
            uint64_t s = 0;
            for (int k = 0; k < 8; k++) s += h[k][b];
            counts[b] += s;
        }
        data += chunk;
        n -= chunk;
    }
}
```
</answer>

This is a segmented odd-only sieve of Eratosthenes. It uses a 32 KiB bit segment, reused across the range, so memory stays well under the 4 MiB limit. Composites are cleared from each base prime's first odd multiple at or above `max(p*p, lo)`, and survivors are counted with `popcount`. The code is not compiled or run here.

<answer>
```c
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define SEG_WORDS 4096
#define SEG_BITS (SEG_WORDS * 64)

static uint64_t seg[SEG_WORDS];

uint64_t count_primes(uint64_t n) {
    if (n < 2) return 0;
    if (n < 3) return 1;

    uint64_t r = (uint64_t)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;

    /* simple sieve for odd base primes up to r */
    uint64_t nb = 0;
    unsigned char *cs = (unsigned char *)calloc(r + 2, 1);
    uint64_t *bp = (uint64_t *)malloc(sizeof(uint64_t) * (r / 2 + 16));
    if (!cs || !bp) { free(cs); free(bp); return 0; }
    for (uint64_t i = 2; i <= r; i++) {
        if (!cs[i]) {
            if (i >= 3) bp[nb++] = i;
            for (uint64_t j = i * i; j <= r; j += i) cs[j] = 1;
        }
    }
    free(cs);

    /* odd numbers 3..n: N = (n+1)/2 - 1 */
    uint64_t N = (n + 1) / 2 - 1;
    uint64_t count = 0;
    uint64_t processed = 0;

    while (processed < N) {
        uint64_t L = N - processed;
        if (L > SEG_BITS) L = SEG_BITS;
        uint64_t lo = 3 + 2 * processed;
        uint64_t top = lo + 2 * (L - 1);
        uint64_t W = (L + 63) / 64;
        for (uint64_t w = 0; w < W; w++) seg[w] = ~0ULL;

        for (uint64_t k = 0; k < nb; k++) {
            uint64_t p = bp[k];
            uint64_t pp = p * p;
            if (pp > top) break;
            uint64_t c = ((lo + p - 1) / p) * p;
            uint64_t start = c > pp ? c : pp;
            if ((start & 1) == 0) start += p;
            uint64_t idx = (start - lo) / 2;
            while (idx < L) {
                seg[idx >> 6] &= ~(1ULL << (idx & 63));
                idx += p;
            }
        }

        uint64_t full = L / 64;
        uint64_t rem = L % 64;
        for (uint64_t w = 0; w < full; w++) count += (uint64_t)__builtin_popcountll(seg[w]);
        if (rem) {
            uint64_t mask = (1ULL << rem) - 1;
            count += (uint64_t)__builtin_popcountll(seg[full] & mask);
        }
        processed += L;
    }

    free(bp);
    return count + 1; /* plus prime 2 */
}
```
</answer>

This is a single-threaded segmented odd-only sieve of Eratosthenes. The segment is a static 32 KiB byte array that stays in cache. Base primes up to sqrt(n) are found with a small sieve, and the segment loop uses only additions, with no per-segment divisions. Total extra memory is about 32 KiB plus a few KiB for base primes. I have not compiled or run it.

<answer>
```c
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdint.h>

#define K_SEG 32768

static unsigned char k_comp[K_SEG];

uint64_t count_primes(uint64_t n) {
    if (n < 2) return 0;
    uint64_t cnt = 1; /* prime 2 */
    if (n < 3) return cnt;

    uint64_t r = (uint64_t)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;

    /* base sieve up to r */
    unsigned char *bs = (unsigned char *)calloc(r + 2, 1);
    if (!bs) return 0;
    uint64_t np = 0;
    for (uint64_t i = 2; i <= r; i++) {
        if (!bs[i]) {
            np++;
            for (uint64_t j = i * i; j <= r; j += i) bs[j] = 1;
        }
    }
    uint64_t *bp = (uint64_t *)malloc(sizeof(uint64_t) * (np + 1));
    uint64_t *nxt = (uint64_t *)malloc(sizeof(uint64_t) * (np + 1));
    if (!bp || !nxt) { free(bs); free(bp); free(nxt); return 0; }
    uint64_t k = 0;
    for (uint64_t i = 3; i <= r; i += 2) {
        if (!bs[i]) {
            bp[k] = i;
            nxt[k] = (i * i - 1) / 2; /* index of i*i */
            k++;
        }
    }
    free(bs);
    uint64_t npr = k;

    uint64_t last = (n & 1) ? n : n - 1;   /* largest odd <= n, >= 3 */
    uint64_t M = (last - 1) / 2;           /* indices 1..M map to 3..last */

    uint64_t s = 1;
    while (s <= M) {
        uint64_t c = M - s + 1;
        if (c > K_SEG) c = K_SEG;
        uint64_t end = s + c;
        memset(k_comp, 1, (size_t)c);
        for (uint64_t j = 0; j < npr; j++) {
            uint64_t p = bp[j];
            uint64_t idx = nxt[j];
            while (idx < end) {
                k_comp[idx - s] = 0;
                idx += p;
            }
            nxt[j] = idx;
        }
        uint64_t sum = 0;
        for (uint64_t i = 0; i < c; i++) sum += k_comp[i];
        cnt += sum;
        s = end;
    }

    free(bp);
    free(nxt);
    return cnt;
}
```
</answer>

This is an LSD radix sort with three 11/11/10-bit passes. It builds all histograms in one read, skips any pass where every element shares the same digit (which helps with the many-duplicates case), and uses one n-element temp buffer (16 MiB at n=4M, under the 20 MiB limit). If the temp allocation fails, it falls back to an in-place heapsort. I have not compiled or run it.

<answer>
```c
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

static void heap_sift_u32(uint32_t *a, size_t start, size_t end) {
    size_t root = start;
    for (;;) {
        size_t child = 2 * root + 1;
        if (child >= end) break;
        if (child + 1 < end && a[child + 1] > a[child]) child++;
        if (a[root] >= a[child]) break;
        uint32_t t = a[root]; a[root] = a[child]; a[child] = t;
        root = child;
    }
}

static void heapsort_u32(uint32_t *a, size_t n) {
    if (n < 2) return;
    for (size_t i = n / 2; i-- > 0;) heap_sift_u32(a, i, n);
    for (size_t end = n - 1; end > 0; end--) {
        uint32_t t = a[0]; a[0] = a[end]; a[end] = t;
        heap_sift_u32(a, 0, end);
    }
}

void sort_u32(uint32_t *a, size_t n) {
    if (n < 2) return;
    if (n < 64) {
        for (size_t i = 1; i < n; i++) {
            uint32_t x = a[i];
            size_t j = i;
            while (j > 0 && a[j - 1] > x) {
                a[j] = a[j - 1];
                j--;
            }
            a[j] = x;
        }
        return;
    }

    static size_t c[3][2048];
    memset(c, 0, sizeof(c));
    for (size_t i = 0; i < n; i++) {
        uint32_t x = a[i];
        c[0][x & 2047]++;
        c[1][(x >> 11) & 2047]++;
        c[2][x >> 22]++;
    }

    uint32_t *tmp = (uint32_t *)malloc(n * sizeof(uint32_t));
    if (!tmp) {
        heapsort_u32(a, n);
        return;
    }

    uint32_t *src = a, *dst = tmp;
    for (int p = 0; p < 3; p++) {
        int shift = (p == 0) ? 0 : (p == 1 ? 11 : 22);
        uint32_t mask = (p < 2) ? 2047u : 1023u;
        /* skip if all elements share this digit */
        uint32_t d0 = (src[0] >> shift) & mask;
        if (c[p][d0] == n) continue;

        size_t sum = 0;
        for (int b = 0; b < 2048; b++) {
            size_t t = c[p][b];
            c[p][b] = sum;
            sum += t;
        }
        for (size_t i = 0; i < n; i++) {
            uint32_t x = src[i];
            size_t d = (x >> shift) & mask;
            dst[c[p][d]++] = x;
        }
        uint32_t *t = src; src = dst; dst = t;
    }

    if (src != a) memcpy(a, src, n * sizeof(uint32_t));
    free(tmp);
}
