This is an LSD radix sort with three 11-bit passes, using one 16 MiB scratch buffer. It skips any pass where all keys share a digit, which helps with heavy duplicates. If `malloc` fails, it falls back to an in-place quicksort. I haven't compiled or timed it.

<answer>
```c
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

static void sort_small_u32(uint32_t *a, ptrdiff_t lo, ptrdiff_t hi) {
    for (ptrdiff_t i = lo + 1; i <= hi; i++) {
        uint32_t v = a[i];
        ptrdiff_t j = i - 1;
        while (j >= lo && a[j] > v) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = v;
    }
}

static void sort_fallback_qs(uint32_t *a, ptrdiff_t lo, ptrdiff_t hi) {
    while (hi - lo > 16) {
        ptrdiff_t mid = lo + (hi - lo) / 2;
        uint32_t x = a[lo], y = a[mid], z = a[hi];
        uint32_t p;
        if (x < y) {
            if (y < z) p = y;
            else if (x < z) p = z;
            else p = x;
        } else {
            if (x < z) p = x;
            else if (y < z) p = z;
            else p = y;
        }
        ptrdiff_t i = lo, j = hi;
        for (;;) {
            while (a[i] < p) i++;
            while (a[j] > p) j--;
            if (i >= j) break;
            uint32_t t = a[i]; a[i] = a[j]; a[j] = t;
            i++; j--;
        }
        /* split: [lo..j] and [j+1..hi] */
        ptrdiff_t split = j;
        if (split - lo < hi - split - 1) {
            sort_fallback_qs(a, lo, split);
            lo = split + 1;
        } else {
            sort_fallback_qs(a, split + 1, hi);
            hi = split;
        }
    }
    sort_small_u32(a, lo, hi);
}

#define RB 11
#define RBUCKETS (1u << RB)
#define RMASK (RBUCKETS - 1u)

void sort_u32(uint32_t *a, size_t n) {
    if (n < 2) return;
    if (n <= 64) {
        sort_small_u32(a, 0, (ptrdiff_t)n - 1);
        return;
    }

    uint32_t *tmp = (uint32_t *)malloc(n * sizeof(uint32_t));
    if (!tmp) {
        sort_fallback_qs(a, 0, (ptrdiff_t)n - 1);
        return;
    }

    static size_t hist[3][RBUCKETS];
    memset(hist, 0, sizeof(hist));

    for (size_t i = 0; i < n; i++) {
        uint32_t x = a[i];
        hist[0][x & RMASK]++;
        hist[1][(x >> 11) & RMASK]++;
        hist[2][(x >> 22) & RMASK]++;
    }

    uint32_t *src = a;
    uint32_t *dst = tmp;
    int swapped = 0;

    for (int p = 0; p < 3; p++) {
        int shift = 11 * p;
        uint32_t d0 = (a[0] >> shift) & RMASK;
        /* if all elements share this digit, skip pass */
        if (hist[p][d0] == n) continue;

        size_t off[RBUCKETS];
        size_t sum = 0;
        for (uint32_t b = 0; b < RBUCKETS; b++) {
            off[b] = sum;
            sum += hist[p][b];
        }
        for (size_t i = 0; i < n; i++) {
            uint32_t x = src[i];
            dst[off[(x >> shift) & RMASK]++] = x;
        }
        uint32_t *t = src; src = dst; dst = t;
        swapped = !swapped;
    }

    if (swapped) {
        memcpy(a, src, n * sizeof(uint32_t));
    }
    free(tmp);
}
```
