#include <arm_neon.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>

static void mm_scalar(const float *A, const float *B, float *C, size_t n,
                      size_t i0, size_t i1, size_t j0, size_t j1) {
    for (size_t i = i0; i < i1; i++) {
        for (size_t j = j0; j < j1; j++) {
            float s = 0.0f;
            for (size_t k = 0; k < n; k++) {
                s += A[i * n + k] * B[k * n + j];
            }
            C[i * n + j] = s;
        }
    }
}

void matmul_f32(const float *A, const float *B, float *C, size_t n) {
    if (n == 0) return;
    size_t n4 = n & ~(size_t)3;
    size_t nj = n & ~(size_t)15;

    float *Bp = NULL;
    if (nj) {
        Bp = (float *)malloc(n * 16 * sizeof(float));
        if (!Bp) {
            mm_scalar(A, B, C, n, 0, n, 0, n);
            return;
        }
    }

    for (size_t jb = 0; jb < nj; jb += 16) {
        for (size_t k = 0; k < n; k++) {
            memcpy(Bp + k * 16, B + k * n + jb, 16 * sizeof(float));
        }
        for (size_t i = 0; i < n4; i += 4) {
            float32x4_t c[4][4];
            for (int r = 0; r < 4; r++)
                for (int v = 0; v < 4; v++)
                    c[r][v] = vdupq_n_f32(0.0f);

            for (size_t k0 = 0; k0 < n4; k0 += 4) {
                float32x4_t a[4];
                for (int r = 0; r < 4; r++)
                    a[r] = vld1q_f32(A + (i + r) * n + k0);

#define MM_STEP(L)                                                         \
                {                                                          \
                    const float *bp = Bp + (k0 + L) * 16;                  \
                    float32x4_t b0 = vld1q_f32(bp);                        \
                    float32x4_t b1 = vld1q_f32(bp + 4);                    \
                    float32x4_t b2 = vld1q_f32(bp + 8);                    \
                    float32x4_t b3 = vld1q_f32(bp + 12);                   \
                    for (int r = 0; r < 4; r++) {                          \
                        c[r][0] = vfmaq_laneq_f32(c[r][0], b0, a[r], L);   \
                        c[r][1] = vfmaq_laneq_f32(c[r][1], b1, a[r], L);   \
                        c[r][2] = vfmaq_laneq_f32(c[r][2], b2, a[r], L);   \
                        c[r][3] = vfmaq_laneq_f32(c[r][3], b3, a[r], L);   \
                    }                                                      \
                }
                MM_STEP(0)
                MM_STEP(1)
                MM_STEP(2)
                MM_STEP(3)
#undef MM_STEP
            }

            for (size_t k = n4; k < n; k++) {
                const float *bp = Bp + k * 16;
                float32x4_t b0 = vld1q_f32(bp);
                float32x4_t b1 = vld1q_f32(bp + 4);
                float32x4_t b2 = vld1q_f32(bp + 8);
                float32x4_t b3 = vld1q_f32(bp + 12);
                for (int r = 0; r < 4; r++) {
                    float av = A[(i + r) * n + k];
                    c[r][0] = vfmaq_n_f32(c[r][0], b0, av);
                    c[r][1] = vfmaq_n_f32(c[r][1], b1, av);
                    c[r][2] = vfmaq_n_f32(c[r][2], b2, av);
                    c[r][3] = vfmaq_n_f32(c[r][3], b3, av);
                }
            }

            for (int r = 0; r < 4; r++) {
                float *out = C + (i + r) * n + jb;
                for (int v = 0; v < 4; v++) {
                    vst1q_f32(out + 4 * v, c[r][v]);
                }
            }
        }
    }

    if (Bp) free(Bp);

    /* Columns beyond nj for rows that were handled by the blocked kernel */
    if (nj < n) {
        mm_scalar(A, B, C, n, 0, n4, nj, n);
    }
    /* Remaining rows (fewer than 4) across all columns */
    if (n4 < n) {
        mm_scalar(A, B, C, n, n4, n, 0, n);
    }
}
