            off[d] = s;
            s += cnt[p][d];
        }
        for (size_t i = 0; i < n; i++) {
            uint32_t v = src[i];
            dst[off[(v >> sh) & m]++] = v;
        }
        uint32_t *t = src;
        src = dst;
        dst = t;
    }
    if (src != a) memcpy(a, src, n * sizeof(uint32_t));
    free(tmp);
}
