This is a segmented, odd-only sieve of Eratosthenes. A mod-105 pattern pre-marks multiples of 3, 5 and 7, and the segment is 32 KiB so it stays cache-resident. The counts for 2, 3, 5 and 7 are added back separately. Memory use is about 32 KiB plus a few KB of base-prime tables, well under the 4 MiB limit. I have not compiled or run it.

<answer>
```c
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define KSEG_SIZE ((size_t)1 << 15)

uint64_t count_primes(uint64_t n) {
    if (n < 2) return 0;
    uint64_t M = (n + 1) / 2;   /* odd values 1,3,5,... <= n ; index i -> value 2i+1 */
    uint64_t total = 1;         /* prime 2 */
    if (n >= 3) total++;
    if (n >= 5) total++;
    if (n >= 7) total++;

    uint8_t pat[105];
    for (int i = 0; i < 105; i++) {
        uint64_t v = 2 * (uint64_t)i + 1;
        pat[i] = (i == 0) || (v % 3 == 0) || (v % 5 == 0) || (v % 7 == 0);
    }
    uint8_t PP[210];
    for (int j = 0; j < 210; j++) PP[j] = pat[j % 105];

    /* integer sqrt */
    uint64_t r = (uint64_t)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;

    /* base primes from 11 to r */
    uint64_t np = 0;
    uint64_t *bp = NULL;
    uint64_t *nxt = NULL;
    uint8_t *bs = NULL;
    if (r >= 11) {
        bs = (uint8_t *)calloc(r + 1, 1);
        bp = (uint64_t *)malloc(sizeof(uint64_t) * (r + 1));
        if (!bs || !bp) { free(bs); free(bp); return 0; }
        for (uint64_t p = 2; p <= r; p++) {
            if (bs[p]) continue;
            if (p >= 11) bp[np++] = p;
            for (uint64_t q = p * p; q <= r; q += p) bs[q] = 1;
        }
        free(bs);
        nxt = (uint64_t *)malloc(sizeof(uint64_t) * (np + 1));
        if (!nxt) { free(bp); return 0; }
        for (uint64_t k = 0; k < np; k++) {
            uint64_t p = bp[k];
            nxt[k] = (p * p - 1) / 2;
        }
    }

    static uint8_t seg[KSEG_SIZE];
    uint64_t zeros = 0;
    for (uint64_t s = 0; s < M; s += KSEG_SIZE) {
        uint64_t len = M - s;
        if (len > KSEG_SIZE) len = KSEG_SIZE;
        /* fill from pattern */
        size_t pos = (size_t)(s % 105);
        size_t copied = 0;
        while (copied < len) {
            size_t chunk = 105;
            if (len - copied < chunk) chunk = len - copied;
            memcpy(seg + copied, PP + pos, chunk);
            copied += chunk;
            pos = (pos + chunk) % 105;
        }
        uint64_t end = s + len;
        for (uint64_t k = 0; k < np; k++) {
            uint64_t p = bp[k];
            uint64_t idx = nxt[k];
            while (idx < end) {
                seg[idx - s] = 1;
                idx += p;
            }
            nxt[k] = idx;
        }
        uint64_t z = 0;
        for (uint64_t i = 0; i < len; i++) z += (seg[i] == 0);
        zeros += z;
    }

    free(bp);
    free(nxt);
    return total + zeros;
}
