static int k_cmp_u32(const void *x, const void *y) {
    uint32_t a = *(const uint32_t *)x, b = *(const uint32_t *)y;
    return (a > b) - (a < b);
}

static size_t k_fallback(const uint32_t *a, size_t n) {
    uint32_t *c = (uint32_t *)malloc(n * sizeof(uint32_t));
    if (!c) {
        /* last resort: O(n^2) is too slow in general, but this is unreachable in practice */
        size_t cnt = 0;
        for (size_t i = 0; i < n; i++) {
            size_t j = 0;
            for (; j < i; j++) if (a[j] == a[i]) break;
            if (j == i) cnt++;
        }
        return cnt;
    }
    for (size_t i = 0; i < n; i++) c[i] = a[i];
    qsort(c, n, sizeof(uint32_t), k_cmp_u32);
    size_t cnt = 0;
    for (size_t i = 0; i < n; i++) {
        if (i == 0 || c[i] != c[i - 1]) cnt++;
    }
    free(c);
    return cnt;
}

size_t count_distinct_u32(const uint32_t *a, size_t n) {
    if (n == 0) return 0;
    uint32_t hi = 0;
    for (size_t i = 0; i < n; i++) hi |= a[i];
    if (hi >> 26) return k_fallback(a, n);

    uint64_t *bits = (uint64_t *)calloc((size_t)1 << 20, sizeof(uint64_t));
    if (!bits) return k_fallback(a, n);

    size_t cnt = 0;
    for (size_t i = 0; i < n; i++) {
        uint32_t v = a[i];
        uint64_t m = 1ull << (v & 63u);
        uint64_t *p = &bits[v >> 6];
        uint64_t o = *p;
        cnt += (size_t)(!(o & m));
        *p = o | m;
    }
    free(bits);
    return cnt;
}
