            uint32_t v = a[i];
            int dup = 0;
            for (size_t j = 0; j < i; j++) {
                if (a[j] == v) { dup = 1; break; }
            }
            c += !dup;
        }
        return c;
    }

    uint64_t *bm = bm_storage;
    size_t cnt = 0;
    for (size_t i = 0; i < n; i++) {
        uint32_t v = a[i];
        uint64_t m = 1ull << (v & 63u);
        uint64_t w = bm[v >> 6];
        cnt += (w & m) == 0;
        bm[v >> 6] = w | m;
    }

    /* clear only what we touched, or everything for large n */
    if (n < 65536) {
        for (size_t i = 0; i < n; i++) {
            bm[a[i] >> 6] = 0;
        }
    } else {
        memset(bm, 0, sizeof(bm_storage));
    }
    return cnt;
}
