#include <arm_neon.h>
#include <stdint.h>
#include <stddef.h>

uint64_t count_substr(const char *text, size_t n, const char *pat, size_t m) {
    if (m == 0) return (uint64_t)(n + 1);
    if (m > n) return 0;
    const uint8_t *t = (const uint8_t *)text;
    const uint8_t *p = (const uint8_t *)pat;
    size_t P = n - m + 1;

    uint8x16_t pv[64];
    for (size_t j = 0; j < m; j++) pv[j] = vdupq_n_u8(p[j]);

    uint64_t total = 0;
    uint8x16_t cnt = vdupq_n_u8(0);
    size_t i = 0;
    int iter = 0;

    while (i + 32 <= P) {
        uint8x16_t a0 = vceqq_u8(vld1q_u8(t + i), pv[0]);
        uint8x16_t a1 = vceqq_u8(vld1q_u8(t + i + 16), pv[0]);
        for (size_t j = 1; j < m; j++) {
            a0 = vandq_u8(a0, vceqq_u8(vld1q_u8(t + i + j), pv[j]));
            a1 = vandq_u8(a1, vceqq_u8(vld1q_u8(t + i + 16 + j), pv[j]));
        }
        cnt = vsubq_u8(cnt, a0);
        cnt = vsubq_u8(cnt, a1);
        i += 32;
        if (++iter == 64) {
            total += vaddlvq_u8(cnt);
            cnt = vdupq_n_u8(0);
            iter = 0;
        }
    }
    if (i + 16 <= P) {
        uint8x16_t a0 = vceqq_u8(vld1q_u8(t + i), pv[0]);
        for (size_t j = 1; j < m; j++) {
            a0 = vandq_u8(a0, vceqq_u8(vld1q_u8(t + i + j), pv[j]));
        }
        cnt = vsubq_u8(cnt, a0);
        i += 16;
    }
    total += vaddlvq_u8(cnt);

    for (; i < P; i++) {
        size_t j = 0;
        while (j < m && t[i + j] == p[j]) j++;
        if (j == m) total++;
    }
    return total;
}
