void transpose_f32(const float *in, float *out, size_t rows, size_t cols) {
    if (rows == 0 || cols == 0) return;
    for (size_t i0 = 0; i0 < rows; i0 += TR_B) {
        size_t i_end = i0 + TR_B < rows ? i0 + TR_B : rows;
        size_t ifull = i0 + ((i_end - i0) / 4) * 4;
        for (size_t j0 = 0; j0 < cols; j0 += TR_B) {
            size_t j_end = j0 + TR_B < cols ? j0 + TR_B : cols;
            size_t jfull = j0 + ((j_end - j0) / 4) * 4;
            for (size_t i = i0; i < ifull; i += 4) {
                for (size_t j = j0; j < jfull; j += 4) {
                    tr_kernel4(in, out, rows, cols, i, j);
