            }
            /* right edge columns for full-row portion */
            for (size_t i = i0; i < ifull; i++) {
                for (size_t j = jfull; j < j_end; j++) {
                    out[j * rows + i] = in[i * cols + j];
                }
            }
            /* bottom edge rows, all columns in tile */
            for (size_t i = ifull; i < i_end; i++) {
                for (size_t j = j0; j < j_end; j++) {
                    out[j * rows + i] = in[i * cols + j];
                }
            }
        }
    }
