#pragma GCC target("+crc")
#include <arm_acle.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>

static inline uint32_t k_apply(const uint32_t *M, uint32_t r) {
    uint32_t x = 0;
    for (int i = 0; i < 32; i++) {
        if ((r >> i) & 1u) x ^= M[i];
    }
    return x;
}

static inline uint64_t k_load64(const uint8_t *p) {
    uint64_t v;
    memcpy(&v, p, 8);
    return v;
}

#define K_BLK 4096u

uint32_t crc32_ieee(const uint8_t *data, size_t n) {
    uint32_t c = 0xFFFFFFFFu;

    if (n >= 3 * (size_t)K_BLK) {
        uint32_t basis1[32];
        uint32_t basis2[32];
        for (int i = 0; i < 32; i++) {
            uint32_t v = 1u << i;
            for (uint32_t j = 0; j < K_BLK; j += 8) {
                v = __crc32d(v, 0);
            }
            basis1[i] = v;
        }
        for (int i = 0; i < 32; i++) {
            basis2[i] = k_apply(basis1, basis1[i]);
        }

        while (n >= 3 * (size_t)K_BLK) {
            const uint8_t *p0 = data;
            const uint8_t *p1 = data + K_BLK;
            const uint8_t *p2 = data + 2 * K_BLK;
            uint32_t a = c, b = 0, d = 0;
            for (uint32_t j = 0; j < K_BLK; j += 8) {
                a = __crc32d(a, k_load64(p0 + j));
                b = __crc32d(b, k_load64(p1 + j));
                d = __crc32d(d, k_load64(p2 + j));
            }
            c = k_apply(basis2, a) ^ k_apply(basis1, b) ^ d;
            data += 3 * (size_t)K_BLK;
            n -= 3 * (size_t)K_BLK;
        }
    }

    while (n >= 8) {
        c = __crc32d(c, k_load64(data));
        data += 8;
        n -= 8;
    }
    while (n > 0) {
        c = __crc32b(c, *data);
        data++;
        n--;
    }
    return ~c;
}
