size_t levenshtein(const char *s, size_t n, const char *t, size_t m)
{
    if (n == 0) return m;
    if (m == 0) return n;

    size_t W = (n + 63) / 64;
    uint64_t *peq = (uint64_t *)calloc(256 * W, sizeof(uint64_t));
