#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <arm_acle.h>
#include <sys/auxv.h>
#include <asm/hwcap.h>

#ifndef HWCAP_CRC32
#define HWCAP_CRC32 (1 << 7)
#endif

#define CRC_B 512u

static uint32_t sw_crc(uint32_t c, const uint8_t *p, size_t n) {
    uint32_t tab[256];
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t v = i;
        for (int k = 0; k < 8; k++)
            v = (v & 1) ? (v >> 1) ^ 0xEDB88320u : (v >> 1);
        tab[i] = v;
    }
    for (size_t i = 0; i < n; i++)
        c = tab[(c ^ p[i]) & 0xFF] ^ (c >> 8);
    return c;
}

__attribute__((target("+crc")))
static void build_shift(uint32_t T[4][256], size_t L) {
    uint32_t Sb[32];
    for (int k = 0; k < 32; k++) {
        uint32_t v = 1u << k;
        for (size_t i = 0; i < L / 8; i++)
            v = __crc32d(v, 0);
        Sb[k] = v;
    }
    for (int j = 0; j < 4; j++) {
        T[j][0] = 0;
        for (unsigned x = 1; x < 256; x++) {
            T[j][x] = T[j][x & (x - 1)] ^ Sb[8 * j + __builtin_ctz(x)];
        }
    }
}

static inline uint32_t apply_shift(const uint32_t T[4][256], uint32_t v) {
    return T[0][v & 255] ^ T[1][(v >> 8) & 255] ^ T[2][(v >> 16) & 255] ^ T[3][v >> 24];
}

__attribute__((target("+crc")))
static uint32_t hw_crc(uint32_t c, const uint8_t *p, size_t n) {
    if (n >= 3 * (size_t)CRC_B) {
        static uint32_t T1[4][256];
        static uint32_t T2[4][256];
        build_shift(T1, CRC_B);
        build_shift(T2, 2 * (size_t)CRC_B);
        while (n >= 3 * (size_t)CRC_B) {
            uint32_t a = c, b = 0, d = 0;
            const uint8_t *p1 = p + CRC_B;
            const uint8_t *p2 = p + 2 * CRC_B;
            for (uint32_t i = 0; i < CRC_B; i += 8) {
                uint64_t x, y, z;
                memcpy(&x, p + i, 8);
                memcpy(&y, p1 + i, 8);
                memcpy(&z, p2 + i, 8);
                a = __crc32d(a, x);
                b = __crc32d(b, y);
                d = __crc32d(d, z);
            }
            c = apply_shift(T2, a) ^ apply_shift(T1, b) ^ d;
            p += 3 * (size_t)CRC_B;
            n -= 3 * (size_t)CRC_B;
        }
    }
    while (n >= 8) {
        uint64_t x;
        memcpy(&x, p, 8);
        c = __crc32d(c, x);
        p += 8;
        n -= 8;
    }
    while (n) {
        c = __crc32b(c, *p);
        p++;
        n--;
    }
    return c;
}

uint32_t crc32_ieee(const uint8_t *data, size_t n) {
    if (n == 0)
        return 0;
    unsigned long hw = getauxval(AT_HWCAP);
    if (hw & HWCAP_CRC32) {
        return ~hw_crc(0xFFFFFFFFu, data, n);
    }
    return ~sw_crc(0xFFFFFFFFu, data, n);
}
