This uses Myers/Hyyrö bit-parallel Levenshtein with 64-bit blocks, so the cost is about n·⌈m/64⌉ word operations (around 564k block steps for the benchmark) rather than 36M DP cells. Memory is about 200 KB for the pattern bitmasks, well under the limit. I have not compiled or run it.

<answer>
```c
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>

size_t levenshtein(const char *s, size_t n, const char *t, size_t m) {
    if (n == 0) return m;
    if (m == 0) return n;

    size_t nb = (m + 63) / 64;
    unsigned r = (unsigned)((m - 1) & 63);

    uint64_t *peq = (uint64_t *)calloc(256 * nb, sizeof(uint64_t));
    uint64_t *Pv = (uint64_t *)malloc(nb * sizeof(uint64_t));
    uint64_t *Mv = (uint64_t *)malloc(nb * sizeof(uint64_t));
    if (!peq || !Pv || !Mv) {
        free(peq); free(Pv); free(Mv);
        return 0;
    }

    for (size_t i = 0; i < m; i++) {
        peq[(size_t)(unsigned char)t[i] * nb + (i >> 6)] |= 1ULL << (i & 63);
    }

    for (size_t b = 0; b < nb; b++) {
        Pv[b] = ~0ULL;
        Mv[b] = 0;
    }

    size_t score = m;
    size_t last = nb - 1;

    for (size_t j = 0; j < n; j++) {
        const uint64_t *Eq = peq + (size_t)(unsigned char)s[j] * nb;
        int hin = 1;
        for (size_t b = 0; b < nb; b++) {
            uint64_t pv = Pv[b];
            uint64_t mv = Mv[b];
            uint64_t eq = Eq[b];
            uint64_t hinNeg = (hin < 0) ? 1ULL : 0ULL;
            uint64_t xv = eq | mv;
            eq |= hinNeg;
            uint64_t xh = (((eq & pv) + pv) ^ pv) | eq;
            uint64_t ph = mv | ~(xh | pv);
            uint64_t mh = pv & xh;
            if (b == last) {
                if ((ph >> r) & 1ULL) score++;
                else if ((mh >> r) & 1ULL) score--;
            }
            int hout = (int)(ph >> 63) - (int)(mh >> 63);
            ph <<= 1;
            mh <<= 1;
            mh |= hinNeg;
            ph |= (hin > 0) ? 1ULL : 0ULL;
            Pv[b] = mh | ~(xv | ph);
            Mv[b] = ph & xv;
            hin = hout;
        }
    }

    free(peq);
    free(Pv);
    free(Mv);
    return score;
}
