```c
#include <stdint.h>
#include <stddef.h>
#include <math.h>
#include <arm_neon.h>

static inline uint64_t mb_group8(const double *crv, double ci, int max_iter)
{
    float64x2_t cr[4], zr[4], zi[4];
    uint64x2_t m[4];
    const float64x2_t civ = vdupq_n_f64(ci);
    const float64x2_t two = vdupq_n_f64(2.0);
    const float64x2_t four = vdupq_n_f64(4.0);
    const uint64x2_t ones = vdupq_n_u64(~0ULL);
    for (int j = 0; j < 4; j++) {
        cr[j] = vld1q_f64(crv + 2 * j);
        zr[j] = vdupq_n_f64(0.0);
        zi[j] = vdupq_n_f64(0.0);
        m[j] = ones;
    }
    for (int k = 0; k < max_iter; k++) {
#pragma GCC unroll 4
        for (int j = 0; j < 4; j++) {
            float64x2_t zr2 = vmulq_f64(zr[j], zr[j]);
            float64x2_t zi2 = vmulq_f64(zi[j], zi[j]);
            float64x2_t t = vmulq_f64(zr[j], zi[j]);
            float64x2_t nzr = vaddq_f64(vsubq_f64(zr2, zi2), cr[j]);
            float64x2_t nzi = vfmaq_f64(civ, t, two);
            float64x2_t r2 = vfmaq_f64(vmulq_f64(nzi, nzi), nzr, nzr);
            m[j] = vandq_u64(m[j], vcleq_f64(r2, four));
            zr[j] = nzr;
            zi[j] = nzi;
        }
        uint64x2_t any = vorrq_u64(vorrq_u64(m[0], m[1]), vorrq_u64(m[2], m[3]));
        if (vmaxvq_u64(any) == 0)
            break;
    }
    uint64_t cnt = 0;
    for (int j = 0; j < 4; j++)
        cnt += vaddvq_u64(vshrq_n_u64(m[j], 63));
    return cnt;
}

uint64_t mandel_count(int w, int h, int max_iter)
{
    if (w <= 0 || h <= 0)
        return 0;
    if (max_iter <= 0)
        return (uint64_t)w * (uint64_t)h;
    uint64_t total = 0;
    double dw = (double)w;
    double dh = (double)h;
    double crv[8];
    for (int py = 0; py < h; py++) {
        double ci = -1.5 + 3.0 * ((py + 0.5) / dh);
        int px = 0;
        for (; px + 8 <= w; px += 8) {
            for (int i = 0; i < 8; i++)
                crv[i] = -2.0 + 3.0 * ((px + i + 0.5) / dw);
            total += mb_group8(crv, ci, max_iter);
        }
        if (px < w) {
            int rem = w - px;
            for (int i = 0; i < 8; i++) {
                if (i < rem)
                    crv[i] = -2.0 + 3.0 * ((px + i + 0.5) / dw);
                else
                    crv[i] = 4.0;
            }
            total += mb_group8(crv, ci, max_iter);
        }
    }
    return total;
}
