This uses the AArch64 CRC32 instructions with three interleaved streams to hide instruction latency. The streams are combined with GF(2) polynomial shifts, the same method zlib's `crc32_combine` uses. I could not compile or run it, so treat it as unverified.

<answer>
```c
#pragma GCC target("+crc")
#include <arm_acle.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>

static uint32_t kz_multmodp(uint32_t a, uint32_t b) {
    uint32_t m = 1u << 31, p = 0;
    for (;;) {
        if (a & m) {
            p ^= b;
            if ((a & (m - 1)) == 0) break;
        }
        m >>= 1;
        b = (b & 1) ? ((b >> 1) ^ 0xEDB88320u) : (b >> 1);
    }
    return p;
}

/* returns x^(8*n) mod P in reflected representation */
static uint32_t kz_x8n(size_t n, const uint32_t *tab) {
    uint32_t p = 1u << 31;
    unsigned k = 3;
    while (n) {
        if (n & 1) p = kz_multmodp(tab[k & 31], p);
        n >>= 1;
        k++;
    }
    return p;
}

static uint32_t kz_seq(const uint8_t *data, size_t n, uint32_t r) {
    while (n >= 8) {
        uint64_t v;
        memcpy(&v, data, 8);
        r = __crc32d(r, v);
        data += 8;
        n -= 8;
    }
    while (n) {
        r = __crc32b(r, *data++);
        n--;
    }
    return r;
}

uint32_t crc32_ieee(const uint8_t *data, size_t n) {
    if (n < 96) {
        return ~kz_seq(data, n, 0xFFFFFFFFu);
    }
    uint32_t tab[32];
    tab[0] = 1u << 30; /* x^1 */
    for (int i = 1; i < 32; i++) tab[i] = kz_multmodp(tab[i - 1], tab[i - 1]);

    size_t L = (n / 3) & ~(size_t)31;
    const uint8_t *pa = data;
    const uint8_t *pb = data + L;
    const uint8_t *pc = data + 2 * L;
    uint32_t ra = 0xFFFFFFFFu, rb = 0, rc = 0;
    for (size_t i = 0; i < L; i += 32) {
        uint64_t a0, a1, a2, a3, b0, b1, b2, b3, c0, c1, c2, c3;
        memcpy(&a0, pa + i, 8);
        memcpy(&a1, pa + i + 8, 8);
        memcpy(&a2, pa + i + 16, 8);
        memcpy(&a3, pa + i + 24, 8);
        memcpy(&b0, pb + i, 8);
        memcpy(&b1, pb + i + 8, 8);
        memcpy(&b2, pb + i + 16, 8);
        memcpy(&b3, pb + i + 24, 8);
        memcpy(&c0, pc + i, 8);
        memcpy(&c1, pc + i + 8, 8);
        memcpy(&c2, pc + i + 16, 8);
        memcpy(&c3, pc + i + 24, 8);
        ra = __crc32d(ra, a0);
        rb = __crc32d(rb, b0);
        rc = __crc32d(rc, c0);
        ra = __crc32d(ra, a1);
        rb = __crc32d(rb, b1);
        rc = __crc32d(rc, c1);
        ra = __crc32d(ra, a2);
        rb = __crc32d(rb, b2);
        rc = __crc32d(rc, c2);
        ra = __crc32d(ra, a3);
        rb = __crc32d(rb, b3);
        rc = __crc32d(rc, c3);
    }
    /* state after A||B||C from init 0xFFFFFFFF */
    uint32_t z = kz_multmodp(kz_x8n(2 * L, tab), ra)
               ^ kz_multmodp(kz_x8n(L, tab), rb)
               ^ rc;
    size_t done = 3 * L;
    z = kz_seq(data + done, n - done, z);
    return ~z;
}
