#include <arm_neon.h>
#include <stdint.h>
#include <stdio.h>

uint64_t mandel_count(int w, int h, int max_iter) {
    uint64_t total = 0;
    if (w <= 0 || h <= 0) return 0;
    for (int py = 0; py < h; py++) {
        double y = -1.5 + 3.0 * (py + 0.5) / h;
        double y2 = y * y;
        for (int px0 = 0; px0 < w; px0 += 8) {
            double cxa[8], cya[8];
            uint64_t dinit[8];
            uint64_t dout[8];
            for (int k = 0; k < 8; k++) {
                int px = px0 + k;
                cya[k] = y;
                if (px < w) {
                    double x = -2.0 + 3.0 * (px + 0.5) / w;
                    double xm = x - 0.25;
                    double q = xm * xm + y2;
                    double x1 = x + 1.0;
                    cxa[k] = x;
                    if (q * (q + xm) <= 0.25 * y2 || x1 * x1 + y2 <= 0.0625) {
                        total++;
                        dinit[k] = ~0ULL;
                    } else {
                        dinit[k] = 0;
                    }
                } else {
                    cxa[k] = 0.0;
                    dinit[k] = ~0ULL;
                }
            }

            float64x2_t cx[4], cy4[4], zx[4], zy[4];
            uint64x2_t dd[4];
            for (int v = 0; v < 4; v++) {
                cx[v] = vld1q_f64(cxa + 2 * v);
                cy4[v] = vld1q_f64(cya + 2 * v);
                zx[v] = vdupq_n_f64(0.0);
                zy[v] = vdupq_n_f64(0.0);
                dd[v] = vld1q_u64(dinit + 2 * v);
            }
            const float64x2_t four = vdupq_n_f64(4.0);
            const float64x2_t two = vdupq_n_f64(2.0);

            int it = 0;
            while (it < max_iter) {
                uint64x2_t all = vandq_u64(vandq_u64(dd[0], dd[1]), vandq_u64(dd[2], dd[3]));
                if ((vgetq_lane_u64(all, 0) & vgetq_lane_u64(all, 1)) == ~0ULL) break;
                int lim = max_iter - it;
                if (lim > 4) lim = 4;
                for (int s = 0; s < lim; s++) {
                    for (int v = 0; v < 4; v++) {
                        float64x2_t x2 = vmulq_f64(zx[v], zx[v]);
                        float64x2_t y2v = vmulq_f64(zy[v], zy[v]);
                        float64x2_t xy = vmulq_f64(zx[v], zy[v]);
                        float64x2_t nx = vaddq_f64(vsubq_f64(x2, y2v), cx[v]);
                        float64x2_t ny = vfmaq_f64(cy4[v], xy, two);
                        float64x2_t r2 = vfmaq_f64(vmulq_f64(nx, nx), ny, ny);
                        zx[v] = nx;
                        zy[v] = ny;
                        dd[v] = vorrq_u64(dd[v], vcgtq_f64(r2, four));
                    }
                }
                it += lim;
            }

            for (int v = 0; v < 4; v++) {
                vst1q_u64(dout + 2 * v, dd[v]);
            }
            for (int k = 0; k < 8; k++) {
                if (px0 + k < w && dout[k] == 0) total++;
            }
        }
    }
    return total;
}
