#include <arm_neon.h>

uint64_t mandel_count(int w, int h, int max_iter) {
    if (w <= 0 || h <= 0) return 0;
    if (max_iter <= 0) return (uint64_t)w * (uint64_t)h;

    uint64_t total = 0;
    const float64x2_t four = vdupq_n_f64(4.0);

    for (int py = 0; py < h; py++) {
        double ci_s = -1.5 + 3.0 * (py + 0.5) / h;
        float64x2_t CI = vdupq_n_f64(ci_s);

        for (int px0 = 0; px0 < w; px0 += 8) {
            double crs[8];
            uint64_t ms[8];
            for (int k = 0; k < 8; k++) {
                int px = px0 + k;
                crs[k] = -2.0 + 3.0 * (px + 0.5) / w;
                ms[k] = (px < w) ? ~(uint64_t)0 : 0;
            }
            float64x2_t cr0 = vld1q_f64(crs + 0);
            float64x2_t cr1 = vld1q_f64(crs + 2);
            float64x2_t cr2 = vld1q_f64(crs + 4);
            float64x2_t cr3 = vld1q_f64(crs + 6);

            uint64x2_t A0 = vld1q_u64(ms + 0);
            uint64x2_t A1 = vld1q_u64(ms + 2);
            uint64x2_t A2 = vld1q_u64(ms + 4);
            uint64x2_t A3 = vld1q_u64(ms + 6);

            float64x2_t zr0 = vdupq_n_f64(0.0), zr1 = zr0, zr2 = zr0, zr3 = zr0;
            float64x2_t zi0 = zr0, zi1 = zr0, zi2 = zr0, zi3 = zr0;

#define MSTEP(zr, zi, A, CR) do { \
                float64x2_t r2_ = vmulq_f64(zr, zr); \
                float64x2_t i2_ = vmulq_f64(zi, zi); \
                A = vandq_u64(A, vcleq_f64(vaddq_f64(r2_, i2_), four)); \
                float64x2_t nzi_ = vfmaq_f64(CI, zr, vaddq_f64(zi, zi)); \
                zr = vaddq_f64(vsubq_f64(r2_, i2_), CR); \
                zi = nzi_; \
