            int it = 0;
            while (it < max_iter) {
                int lim = (max_iter - it < 4) ? max_iter : it + 4;
                for (; it < lim; it++) {
                    MSTEP(zr0, zi0, A0, cr0);
                    MSTEP(zr1, zi1, A1, cr1);
                    MSTEP(zr2, zi2, A2, cr2);
                    MSTEP(zr3, zi3, A3, cr3);
