                float64x2_t m0 = vaddq_f64(vmulq_f64(zr0, zr0), vmulq_f64(zi0, zi0));
                float64x2_t m1 = vaddq_f64(vmulq_f64(zr1, zr1), vmulq_f64(zi1, zi1));
                float64x2_t m2 = vaddq_f64(vmulq_f64(zr2, zr2), vmulq_f64(zi2, zi2));
